import type { Card } from '../cards/card.js';
import { mermaidLabel } from './mermaid-label.js';

// RF-261, RF-508, DEC-134: the screen map, a Mermaid flowchart generated by code from the "leads
// to" links of the SCRN cards; the model never writes Mermaid. One node per screen card in card id
// order, labelled with its route (its title when it has no screen detail); a link names a screen
// by card id or by route, and a link to a screen without a card gets one node of its own. Node
// ids are generated (`s1`, `s2`, ...), never taken from the code; every label goes through
// `mermaidLabel`; no node gets a click, a link or a style.

interface Nodes {
  readonly lines: string[];
  /** Keys carry a prefix, so a route can never be taken for a card id. */
  readonly idOf: Map<string, string>;
}

function node(nodes: Nodes, key: string, label: string): string {
  const known = nodes.idOf.get(key);
  if (known !== undefined) return known;
  const id = `s${String(nodes.idOf.size + 1)}`;
  nodes.idOf.set(key, id);
  nodes.lines.push(`  ${id}["${mermaidLabel(label)}"]`);
  return id;
}

function byId(left: Card, right: Card): number {
  if (left.id === right.id) return 0;
  return left.id < right.id ? -1 : 1;
}

/** Places every screen card, then names each route by the first card that has it. */
function placeScreens(nodes: Nodes, screens: readonly Card[]): Map<string, string> {
  const routes = new Map<string, string>();
  for (const screen of screens) {
    const id = node(nodes, `card ${screen.id}`, screen.screen?.route ?? screen.title);
    const route = screen.screen?.route;
    if (route !== undefined && !routes.has(`route ${route}`)) routes.set(`route ${route}`, id);
  }
  return routes;
}

// RF-261
export function screenMapDiagram(cards: readonly Card[]): string {
  const screens = cards.filter((card) => card.type === 'SCRN').toSorted(byId);
  const nodes: Nodes = { lines: [], idOf: new Map() };
  const routes = placeScreens(nodes, screens);
  const links = new Set<string>();
  for (const screen of screens) {
    const from = node(nodes, `card ${screen.id}`, screen.title);
    for (const target of screen.screen?.leadsTo ?? []) {
      const key = `route ${target}`;
      const to = nodes.idOf.get(`card ${target}`) ?? routes.get(key) ?? node(nodes, key, target);
      links.add(`  ${from} --> ${to}`);
    }
  }
  return ['flowchart LR', ...nodes.lines, ...links, ''].join('\n');
}
